package com.nextaicommerce.platform.marketplace;
import com.nextaicommerce.platform.catalog.CatalogRepository;import com.nextaicommerce.platform.web.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.mock.web.MockHttpSession;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.authority.SimpleGrantedAuthority;import org.springframework.test.util.ReflectionTestUtils;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MarketplaceMappingDraftControllerTest{
 @Test void draftReadUsesSelectedAccountAndOnlyAnAuthorizedSelectedStore()throws Exception{
  UUID tenant=UUID.randomUUID(),store=UUID.randomUUID();var workspace=mock(WorkspaceAccessRepository.class);var draft=mock(MarketplaceMappingDraft.class);var repo=mock(MarketplaceSkuRepository.class);var controller=new MarketplaceSkuController(repo,workspace,mock(CatalogRepository.class));ReflectionTestUtils.setField(controller,"mappingDraft",draft);var session=new MockHttpSession();session.setAttribute("selectedTenantId",tenant);session.setAttribute(AccountSelectionController.STORE_ID,store);var auth=new UsernamePasswordAuthenticationToken("operator@example.invalid","unused",List.of(new SimpleGrantedAuthority("ROLE_OPERATOR")));when(workspace.findConnection(tenant,store)).thenReturn(new WorkspaceAccessRepository.ConnectionIdentity(store,"AMAZON"));var mvc=MockMvcBuilders.standaloneSetup(controller).build();
  mvc.perform(get("/app/marketplace-skus/mappings/draft").param("sku","IB-299402-3xEA").session(session).principal(auth)).andExpect(status().isForbidden());verifyNoInteractions(draft);
  when(workspace.canOperateAccount(tenant,auth.getName())).thenReturn(true);when(workspace.listAccountOptions(auth.getName(),false)).thenReturn(List.of(new WorkspaceAccessRepository.AccountOption(tenant,"Own","O",null,List.of())));
  mvc.perform(get("/app/marketplace-skus/mappings/draft").param("sku","IB-299402-3xEA").session(session).principal(auth)).andExpect(status().isForbidden());verifyNoInteractions(draft);
  var connection=new WorkspaceAccessRepository.ConnectionView(store,tenant,"Own","Store","AMAZON","seller","US","US","","ACTIVE",null,false);when(workspace.listAccountOptions(auth.getName(),false)).thenReturn(List.of(new WorkspaceAccessRepository.AccountOption(tenant,"Own","O",null,List.of(connection))));when(draft.suggest(tenant,"IB-299402-3xEA")).thenReturn(new MarketplaceMappingDraft.Suggestion(3,null));
  mvc.perform(get("/app/marketplace-skus/mappings/draft").param("sku","IB-299402-3xEA").param("tenantId",UUID.randomUUID().toString()).session(session).principal(auth)).andExpect(status().isOk()).andExpect(jsonPath("$.quantity").value(3));verify(draft).suggest(tenant,"IB-299402-3xEA");verifyNoInteractions(repo);
 }
}
